import { randomUUID } from 'node:crypto';
import { Test, TestingModule } from '@nestjs/testing';
import {
  E2EAuthService,
  E2EDbService,
  E2EGraphqlResponse,
  E2EHttpClient,
  E2EHttpService,
  E2EStackService,
  TestContext,
  TestingInfraModule,
} from '../../infra';

/**
 * fr.recur full lifecycle, one A->Z journey through the public GraphQL door only: a fresh account
 * creates a task, makes it a recurring rule, watches the api's own in-process generator
 * (integration.recur.scheduler, per-second RECUR_TICK_CRON on the run-owned stack) materialise real
 * occurrences, edits the rule and observes new occurrences carry the new shape while materialised
 * history is untouched, then ends the rule and verifies - over the API and out-of-band through
 * E2EDbService - that no new occurrence is ever generated again.
 */

// The frozen public transport contract (same documents the proven JS harness sends).
const CREATE_TASK =
  'mutation CreateTask($input: CreateTaskInput!) { createTask(input: $input) { taskId title } }';
const LIST_TASKS = 'query { tasks { taskId title complete } }';
const MAKE_RECURRING =
  'mutation MakeRecurring($input: MakeRecurringInput!) { makeRecurring(input: $input) { ruleId title frequency timeZone time startDate } }';
const EDIT_RECURRENCE =
  'mutation EditRecurrence($input: EditRecurrenceInput!) { editRecurrence(input: $input) { ruleId frequency timeZone time } }';
const END_RECURRENCE =
  'mutation EndRecurrence($input: EndRecurrenceInput!) { endRecurrence(input: $input) { ruleId endedAt orphanedCount } }';
const UPCOMING_OCCURRENCES =
  'query Upcoming($ruleId: String!) { upcomingOccurrences(ruleId: $ruleId) { ruleId materialised { occurrenceId localDate dueAtUtc status } previewDates } }';

interface MaterialisedRow {
  occurrenceId: string;
  localDate: string;
  dueAtUtc: string;
  status: string;
}
interface UpcomingData {
  upcomingOccurrences: { ruleId: string; materialised: MaterialisedRow[]; previewDates: string[] };
}
interface CreateTaskData {
  createTask: { taskId: string; title: string };
}
interface TasksData {
  tasks: { taskId: string; title: string; complete: boolean }[];
}
interface MakeRecurringData {
  makeRecurring: {
    ruleId: string;
    title: string;
    frequency: string;
    timeZone: string;
    time: string;
    startDate: string;
  };
}
interface EditRecurrenceData {
  editRecurrence: { ruleId: string; frequency: string; timeZone: string; time: string };
}
interface EndRecurrenceData {
  endRecurrence: { ruleId: string; endedAt: string; orphanedCount: number };
}

function unwrap<T>(envelope: E2EGraphqlResponse<T>, operation: string): T {
  if (envelope.errorCode || envelope.data === null) {
    throw new Error(
      `${operation} failed: ${envelope.errorCode ?? 'no-code'} ${envelope.errorMessage ?? ''}`.trim(),
    );
  }
  return envelope.data;
}

function utcDateOffset(days: number): string {
  return new Date(Date.now() + days * 86_400_000).toISOString().slice(0, 10);
}

function addDaysUtc(date: string, days: number): string {
  const [year, month, day] = date.split('-').map(Number);
  return new Date(Date.UTC(year, month - 1, day + days)).toISOString().slice(0, 10);
}

/** Every date an every-n-days rule fires on inside [startDate, horizon] - independent re-walk of the
 *  rule's own calendar arithmetic, computed here so the assertion does not borrow the app's answer. */
function expectedNDaysDates(startDate: string, n: number, horizon: string): string[] {
  const dates: string[] = [];
  let elapsed = 0;
  for (let cursor = startDate; cursor <= horizon; cursor = addDaysUtc(cursor, 1), elapsed += 1) {
    if (elapsed % n === 0) dates.push(cursor);
  }
  return dates;
}

/** Polls a public read until it shows what the stack is expected to have produced, or gives up. */
async function waitFor<T>(
  label: string,
  probe: () => Promise<{ done: boolean; value: T }>,
  timeoutMs = 120_000,
): Promise<T> {
  const startedAt = Date.now();
  let last: T | undefined;
  while (Date.now() - startedAt < timeoutMs) {
    const observed = await probe();
    last = observed.value;
    if (observed.done) return observed.value;
    await new Promise((resolve) => setTimeout(resolve, 1_500));
  }
  throw new Error(
    `timed out after ${timeoutMs}ms waiting for ${label}; last observation: ${JSON.stringify(last ?? null).slice(0, 700)}`,
  );
}

describe('recur: recurrence lifecycle (e2e)', () => {
  let moduleRef: TestingModule;
  let stack: E2EStackService;
  let http: E2EHttpService;
  let auth: E2EAuthService;
  let db: E2EDbService;
  let personId: string | null = null;

  beforeAll(async () => {
    moduleRef = await Test.createTestingModule({
      imports: [TestingInfraModule.register({ context: TestContext.E2E })],
    }).compile();
    await moduleRef.init();
    stack = moduleRef.get(E2EStackService);
    http = moduleRef.get(E2EHttpService);
    auth = moduleRef.get(E2EAuthService);
    db = moduleRef.get(E2EDbService);
    expect(stack.apiBaseUrl).toMatch(/^http:\/\/127\.0\.0\.1:\d+$/);
    // The stack counts as up only when the api answers its dependency-checked /health.
    const health = await http.client().get<{ status: string }>('/health');
    expect(health.data.status).toBe('ok');
  }, 600_000);

  afterAll(async () => {
    try {
      if (personId) await auth.deleteAccount(personId);
    } finally {
      await moduleRef?.close();
    }
  }, 120_000);

  it('create task -> make recurring -> occurrences -> edit rule -> occurrences reflect edit -> end rule -> no new occurrences', async () => {
    const runId = randomUUID().slice(0, 8);
    const email = `e2e-recur-${runId}@todo.dev`;
    const password = `e2e-pass-${runId}`;

    // Step 1 - a fresh account signs in and owns a plain task before anything recurs.
    personId = (await auth.createAccount({ email, password })).personId;
    const session = await auth.signIn(email, password);
    const me: E2EHttpClient = http.client({ bearerToken: session.sessionToken });

    const title = `e2e:recur-lifecycle:${runId}`;
    const created = unwrap(
      await me.graphql<CreateTaskData>(CREATE_TASK, { input: { title } }),
      'createTask',
    );
    expect(created.createTask.taskId).toBeTruthy();
    expect(created.createTask.title).toBe(title);

    // Step 2 - the task becomes a weekly (n=7) rule that began 21 days ago at 09:00 UTC.
    const startDate = utcDateOffset(-21);
    const today = utcDateOffset(0);
    const rule = unwrap(
      await me.graphql<MakeRecurringData>(MAKE_RECURRING, {
        input: {
          title,
          // The schema exposes RecurFrequency by enum key; the response still echoes the stored
          // 'every-n-days' value string.
          frequency: 'EveryNDays',
          n: 7,
          timeZone: 'UTC',
          time: '09:00',
          startDate,
        },
      }),
      'makeRecurring',
    ).makeRecurring;
    expect(rule).toMatchObject({
      title,
      frequency: 'every-n-days',
      timeZone: 'UTC',
      time: '09:00',
      startDate,
    });
    const ruleId = rule.ruleId;

    const readUpcoming = async () =>
      unwrap(
        await me.graphql<UpcomingData>(UPCOMING_OCCURRENCES, { ruleId }),
        'upcomingOccurrences',
      ).upcomingOccurrences;

    // Step 3 - real generator ticks backfill [startDate, today]: -21, -14, -7, 0 at 09:00 UTC.
    const expectedBefore = expectedNDaysDates(startDate, 7, today);
    expect(expectedBefore).toHaveLength(4);
    const beforeEdit = await waitFor(`occurrences for n=7 rule ${ruleId}`, async () => {
      const upcoming = await readUpcoming();
      return { done: upcoming.materialised.length >= expectedBefore.length, value: upcoming };
    });
    expect(beforeEdit.materialised.map((row) => row.localDate).sort()).toEqual(expectedBefore);
    for (const row of beforeEdit.materialised) {
      expect(row.status).toBe('materialised');
      expect(row.dueAtUtc.endsWith('T09:00:00.000Z')).toBe(true);
    }
    // The preview is computed live and reaches past the materialised history.
    expect(beforeEdit.previewDates.length).toBeGreaterThan(0);
    // Each materialised occurrence is a real task row - occurrenceId is the created task's id.
    const tasks = unwrap(await me.graphql<TasksData>(LIST_TASKS), 'tasks').tasks;
    const taskIds = new Set(tasks.map((task) => task.taskId));
    for (const row of beforeEdit.materialised) {
      expect(taskIds.has(row.occurrenceId)).toBe(true);
    }

    // Step 4 - edit the rule: cadence n=7 -> n=3, local time 09:00 -> 18:00.
    const edited = unwrap(
      await me.graphql<EditRecurrenceData>(EDIT_RECURRENCE, {
        input: { ruleId, n: 3, time: '18:00' },
      }),
      'editRecurrence',
    ).editRecurrence;
    expect(edited).toEqual({ ruleId, frequency: 'every-n-days', timeZone: 'UTC', time: '18:00' });

    // Step 5 - occurrences reflect the edit: the n=3 walk covers -18,-15,-12,-9,-6,-3 in addition to
    // the dates already materialised; those new rows fire at 18:00 while old rows stay byte-identical.
    const expectedEdited = expectedNDaysDates(startDate, 3, today);
    const expectedUnion = [...new Set([...expectedBefore, ...expectedEdited])].sort();
    expect(expectedUnion).toHaveLength(10);
    const beforeIds = new Set(beforeEdit.materialised.map((row) => row.occurrenceId));
    const afterEdit = await waitFor(`n=3 occurrences for rule ${ruleId}`, async () => {
      const upcoming = await readUpcoming();
      return { done: upcoming.materialised.length >= expectedUnion.length, value: upcoming };
    });
    expect(afterEdit.materialised.map((row) => row.localDate).sort()).toEqual(expectedUnion);
    for (const row of afterEdit.materialised) {
      if (beforeIds.has(row.occurrenceId)) {
        const original = beforeEdit.materialised.find((old) => old.occurrenceId === row.occurrenceId);
        expect(row).toEqual(original);
      } else {
        expect(row.status).toBe('materialised');
        expect(row.dueAtUtc.endsWith('T18:00:00.000Z')).toBe(true);
      }
    }

    // Step 6 - end the rule effective today: today's row orphans, history is preserved.
    const ended = unwrap(
      await me.graphql<EndRecurrenceData>(END_RECURRENCE, {
        input: { ruleId, endedAt: today },
      }),
      'endRecurrence',
    ).endRecurrence;
    expect(ended.ruleId).toBe(ruleId);
    expect(ended.endedAt).toBe(today);
    expect(ended.orphanedCount).toBe(1);

    const atEnd = await readUpcoming();
    expect(atEnd.previewDates).toEqual([]);
    expect(atEnd.materialised.map((row) => row.localDate).sort()).toEqual(expectedUnion);
    for (const row of atEnd.materialised) {
      expect(row.status).toBe(row.localDate >= today ? 'orphaned' : 'materialised');
    }

    // Step 7 - no new occurrences: across several more real ticks the materialised set stays frozen
    // at the dates the rule had already covered, and nothing is ever dated after endedAt.
    const frozenCount = atEnd.materialised.length;
    await new Promise((resolve) => setTimeout(resolve, 5_000));
    const later = await readUpcoming();
    expect(later.materialised).toHaveLength(frozenCount);
    expect(later.materialised.filter((row) => row.localDate > today)).toEqual([]);
    expect(later.previewDates).toEqual([]);

    // Out-of-band verify on the run-owned postgres: the rule row is ended and no occurrence row
    // exists past the end date (seed/verify only - the flow above never touched the database).
    const ruleRows = await db.query<{ ended_at: string }>(
      'select ended_at from recurrence_rules where id = $1',
      [ruleId],
    );
    expect(ruleRows).toEqual([{ ended_at: today }]);
    const statusRows = await db.query<{ status: string; count: number }>(
      'select status, count(*)::int as count from occurrences where rule_id = $1 group by status order by status',
      [ruleId],
    );
    expect(statusRows).toEqual([
      { status: 'materialised', count: frozenCount - 1 },
      { status: 'orphaned', count: 1 },
    ]);
    const pastEnd = await db.query<{ count: number }>(
      'select count(*)::int as count from occurrences where rule_id = $1 and local_date > $2',
      [ruleId, today],
    );
    expect(pastEnd[0].count).toBe(0);
  }, 300_000);
});

/**
 * Lane E2E-09 contract adapter + docker observation helpers.
 *
 * These specs are written against the frozen E2E-00/E2E-06 infra contract (ex-testing/ANALYSIS.md
 * §5): `TestingInfraModule.register({context})` as the spec's only import, `E2EStackService` owning
 * compose up on module init and `down -v` on shutdown. The infra modules are loaded dynamically so
 * the specs skip with an explicit reason while the owning lanes have not landed them, instead of
 * failing module resolution. Contract lookups are deliberately duck-typed (deep-scan for the live
 * compose project name, probe discovered loopback URLs for /health) so property-name choices in the
 * infra implementation do not break these specs.
 */
import { execFileSync } from 'node:child_process';
import * as path from 'node:path';

/* eslint-disable @typescript-eslint/no-explicit-any */

export interface E2EInfra {
  Test: any;
  TestingInfraModule: any;
  TestContext: any;
  E2EStackService: any;
}

export interface InfraLoad {
  infra: E2EInfra | null;
  reason: string | null;
}

export function loadInfra(e2eDir: string): InfraLoad {
  let Test: any;
  try {
    Test = require('@nestjs/testing').Test;
  } catch (e) {
    return { infra: null, reason: `@nestjs/testing not resolvable: ${(e as Error).message}` };
  }
  // The module tree lives at src/tests/infra (sibling of e2e/), per the v2 layout.
  const infraDir = path.resolve(e2eDir, '..', 'infra');
  try {
    const mod = require(path.join(infraDir, 'testing-infra.module'));
    const stack = require(path.join(infraDir, 'platform', 'stack', 'e2e-stack.service'));
    let options: any = {};
    try {
      options = require(path.join(infraDir, 'testing-infra.options'));
    } catch {
      // Contract variants that keep TestContext on the module file export it there instead.
    }
    if (!mod?.TestingInfraModule) {
      return { infra: null, reason: 'infra/testing-infra.module does not export TestingInfraModule' };
    }
    if (!stack?.E2EStackService) {
      return { infra: null, reason: 'infra/platform/stack/e2e-stack.service does not export E2EStackService' };
    }
    return {
      infra: {
        Test,
        TestingInfraModule: mod.TestingInfraModule,
        TestContext: mod.TestContext ?? stack.TestContext ?? options.TestContext,
        E2EStackService: stack.E2EStackService,
      },
      reason: null,
    };
  } catch (e) {
    return { infra: null, reason: `e2e infra module not loadable (E2E-00/E2E-06 contract pending): ${(e as Error).message}` };
  }
}

/** Boots the contract module and returns the testing module ref plus the stack service instance. */
export async function bootE2EModule(infra: E2EInfra, specId?: string): Promise<{ moduleRef: any; stack: any }> {
  const moduleRef = await infra.Test.createTestingModule({
    imports: [infra.TestingInfraModule.register({ context: infra.TestContext?.E2E ?? 'e2e', specId })],
  }).compile();
  await moduleRef.init();
  return { moduleRef, stack: moduleRef.get(infra.E2EStackService) };
}

export function docker(args: string[]): string {
  return execFileSync('docker', args, { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 }).trim();
}

export function dockerLines(args: string[]): string[] {
  const out = docker(args);
  return out ? out.split(/\r?\n/).map((line) => line.trim()).filter(Boolean) : [];
}

export function dockerAvailable(): boolean {
  try {
    execFileSync('docker', ['version', '--format', '{{.Server.Version}}'], { stdio: 'pipe', timeout: 20_000 });
    return true;
  } catch {
    return false;
  }
}

/** Every compose project label currently present on the daemon — the ground truth the stack's own
 * project-name field is matched against, so no accessor-name guess is needed. */
function liveComposeProjects(): Set<string> {
  const labels = dockerLines(['ps', '-a', '--format', '{{.Label "com.docker.compose.project"}}']);
  return new Set(labels.filter(Boolean));
}

/** Finds the run-scoped compose project name wherever the stack service stores it. */
export function composeProjectOf(stack: unknown): string | null {
  const live = liveComposeProjects();
  let found: string | null = null;
  const scan = (value: any, depth: number): void => {
    if (found !== null || value === null || value === undefined || depth < 0) return;
    if (typeof value === 'string') {
      if (live.has(value)) found = value;
      return;
    }
    if (typeof value === 'object') {
      for (const key of Object.keys(value)) scan(value[key], depth - 1);
    }
  };
  scan(stack, 5);
  return found;
}

/** All loopback http(s) URLs stored anywhere on the stack object (baseUrl fields, per-service urls). */
export function loopbackUrlsOf(stack: unknown): string[] {
  const urls = new Set<string>();
  const scan = (value: any, depth: number): void => {
    if (value === null || value === undefined || depth < 0) return;
    if (typeof value === 'string') {
      if (/^https?:\/\/(127\.0\.0\.1|localhost)(:\d+)?/.test(value)) urls.add(value.replace(/\/+$/, ''));
      return;
    }
    if (typeof value === 'object') {
      for (const key of Object.keys(value)) scan(value[key], depth - 1);
    }
  };
  scan(stack, 5);
  return [...urls];
}

export async function httpStatus(url: string, timeoutMs = 5_000): Promise<number | null> {
  try {
    const response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
    await response.arrayBuffer().catch(() => undefined);
    return response.status;
  } catch {
    return null;
  }
}

/** The subset of discovered URLs answering `GET /health` with `{status:'ok'}` — the api doors only. */
export async function apiHealthUrls(stack: unknown): Promise<string[]> {
  const apis: string[] = [];
  for (const base of loopbackUrlsOf(stack)) {
    try {
      const response = await fetch(`${base}/health`, { signal: AbortSignal.timeout(4_000) });
      if (response.status !== 200) continue;
      const body = (await response.json()) as { status?: string };
      if (body?.status === 'ok') apis.push(base);
    } catch {
      // Not an api door (keycloak, etc.) — ignore.
    }
  }
  return apis;
}

/** Compose service names this run actually has containers for — from docker labels, so the spec
 * never hardcodes the stack's spelling or needs the compose file's run-scoped env vars. */
export function projectServices(project: string): string[] {
  const labels = dockerLines([
    'ps', '-a',
    '--filter', `label=com.docker.compose.project=${project}`,
    '--format', '{{.Label "com.docker.compose.service"}}',
  ]);
  return [...new Set(labels.filter(Boolean))];
}

/** Container id of one compose service inside the run's project. */
export function projectContainer(project: string, service: string): string | null {
  return (
    dockerLines([
      'ps', '-a',
      '--filter', `label=com.docker.compose.project=${project}`,
      '--filter', `label=com.docker.compose.service=${service}`,
      '--format', '{{.ID}}',
    ])[0] ?? null
  );
}

/**
 * Kill and later restart one service container with plain docker. Deliberately not
 * `docker compose kill/up`: those re-interpolate the compose file and this spec does not own the
 * run-scoped env (ports, credentials) the stack service expanded at boot time. `docker start` puts
 * back the identical container - same published ports, same volumes.
 */
export function killService(project: string, servicePattern: RegExp): { service: string; id: string } {
  const service = projectServices(project).find((name) => servicePattern.test(name));
  if (!service) throw new Error(`no service matching ${servicePattern} in project ${project}`);
  const id = projectContainer(project, service);
  if (!id) throw new Error(`no container for service ${service} in project ${project}`);
  docker(['kill', id]);
  return { service, id };
}

export function startContainer(id: string): void {
  docker(['start', id]);
}

export async function retryUntil(
  label: string,
  timeoutMs: number,
  probe: () => Promise<boolean>,
  intervalMs = 1_000,
): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  let last: unknown;
  while (Date.now() < deadline) {
    try {
      if (await probe()) return;
    } catch (e) {
      last = e;
    }
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
  throw new Error(`timed out waiting for ${label}${last ? ` (last error: ${last})` : ''}`);
}

