/**
 * Lane E2E-09 — infra-down recovery (todo-app-backend).
 *
 * Boots the run-scoped stack, kills the postgres container mid-run (the one dependency the api's
 * /health door probes), asserts the api stays alive and answers with a clean 503 instead of hanging
 * or crashing, starts the same container back (identical ports/volume), and asserts the api recovers
 * to 200. Written against the frozen E2E-00 contract (ex-testing/ANALYSIS.md §5); skips with a
 * reason while that infra has not landed.
 */
import * as path from 'node:path';
import {
  apiHealthUrls,
  bootE2EModule,
  composeProjectOf,
  dockerAvailable,
  httpStatus,
  killService,
  loadInfra,
  retryUntil,
  startContainer,
} from './e2e-infra-contract';

const E2E_DIR = path.resolve(__dirname, '..');
const { infra, reason } = loadInfra(E2E_DIR);
const runnable = infra !== null && dockerAvailable();
if (!runnable) {
  console.warn(`[e2e-09] infra-recovery skipped: ${reason ?? 'docker daemon not reachable'}`);
}
const describeE2E = runnable ? describe : describe.skip;

describeE2E('resilience: infra recovery', () => {
  jest.setTimeout(600_000);

  it('postgres outage yields a clean api error and the api recovers when postgres returns', async () => {
    const { moduleRef, stack } = await bootE2EModule(infra!, 'resilience/infra-recovery');
    try {
      const project = composeProjectOf(stack);
      expect(project).not.toBeNull();

      const apis = await apiHealthUrls(stack);
      expect(apis.length).toBeGreaterThan(0);

      const killed = killService(project!, /postgres/i);

      // The api tolerates the outage: still answering HTTP, with a declared dependency error.
      for (const base of apis) {
        await retryUntil(`${base}/health answers 503`, 60_000, async () => (await httpStatus(`${base}/health`, 15_000)) === 503);
      }

      startContainer(killed.id);

      for (const base of apis) {
        await retryUntil(`${base}/health recovers to 200`, 180_000, async () => (await httpStatus(`${base}/health`)) === 200);
      }
    } finally {
      await moduleRef.close().catch(() => undefined);
    }
  });
});

