import { Test, TestingModule } from '@nestjs/testing';
import {
  E2E_BOOT_TIMEOUT_MS,
  E2EAuthService,
  E2EDbService,
  E2EHttpService,
  E2EStackService,
  TestContext,
  TestingInfraModule,
} from '../../infra';

jest.setTimeout(120_000);

// taskCounts has no GRAPHQL_DOCUMENTS entry yet - the registry names only the doors the retired
// JS harness exercised; a raw document string is the supported escape hatch for the rest.
const TASK_COUNTS = 'query TaskCounts { taskCounts { open complete } }';

// The run-owned realm seeds this identity (.starcistacks/dev/infra/compose/realm-todo.json).
const DEMO = { email: 'demo@todo.dev', password: 'todo-demo-pass' };

interface TaskSummary {
  taskId: string;
  title: string;
  complete: boolean;
}

interface TaskCounts {
  open: number;
  complete: number;
}

interface TaskRow {
  id: string;
  owner: string;
  title: string;
  complete: boolean;
  completed_at: Date | null;
}

interface CountRow {
  count: number;
}

/**
 * fr.task.* as one A→Z journey over the real stack: sign in, create a task, read it back out
 * of the list, complete it, reopen it, watch taskCounts track each transition, then sign out
 * and find the door closed. The Postgres reads are out-of-band verification only - every step
 * of the journey itself travels the real /graphql door.
 */
describe('task lifecycle (e2e)', () => {
  let moduleRef: TestingModule;
  let auth: E2EAuthService;
  let db: E2EDbService;
  let http: E2EHttpService;

  beforeAll(async () => {
    moduleRef = await Test.createTestingModule({
      imports: [TestingInfraModule.register({ context: TestContext.E2E })],
    })
      // init() fires every provider's onModuleInit in parallel, so the db service would build its
      // datasource while stack.databaseUrl is still '' (set inside boot). Shadowing the hook keeps
      // the real service but lets it connect lazily on first query, once the url exists.
      .overrideProvider(E2EDbService)
      .useFactory({
        factory: (stack: E2EStackService) => {
          const service = new E2EDbService(stack);
          (service as { onModuleInit?: unknown }).onModuleInit = undefined;
          return service;
        },
        inject: [E2EStackService],
      })
      .compile();
    await moduleRef.init();
    auth = moduleRef.get(E2EAuthService);
    db = moduleRef.get(E2EDbService);
    http = moduleRef.get(E2EHttpService);
    // The stack counts as up only when the api answers its dependency-checked /health.
    expect((await http.anonymous().get<{ status: string }>('/health')).data.status).toBe('ok');
  }, E2E_BOOT_TIMEOUT_MS);

  afterAll(async () => {
    // close() runs the stack's teardown: compose down -v plus the verified-gone check, which
    // throws here if any container or volume of this run's project remains.
    await moduleRef?.close();
  });

  it('sign-in → create → list → complete → reopen → counts → sign-out', async () => {
    const title = `e2e lifecycle ${Date.now()}`;
    const session = await auth.signIn(DEMO.email, DEMO.password);
    const token = session.token;
    const personId = session.personId;

    const countsOf = async (): Promise<TaskCounts> => {
      const res = await http.graphql<{ taskCounts: TaskCounts }>(TASK_COUNTS, { token });
      expect(res.errors).toBeNull();
      return res.data!.taskCounts;
    };
    const baseline = await countsOf();

    const created = await http.graphql<{ createTask: { taskId: string; title: string } }>(
      'createTask',
      { variables: { input: { title } }, token },
    );
    expect(created.errors).toBeNull();
    const taskId = created.data!.createTask.taskId;
    expect(taskId).toEqual(expect.any(String));
    expect(created.data!.createTask.title).toBe(title);

    // There is no single-task query in this schema: a task is read back out of its owner's list.
    const listed = await http.graphql<{ tasks: TaskSummary[] }>('listTasks', { token });
    expect(listed.errors).toBeNull();
    expect(listed.data!.tasks.find((task) => task.taskId === taskId)).toEqual({
      taskId,
      title,
      complete: false,
    });
    expect(await countsOf()).toEqual({ open: baseline.open + 1, complete: baseline.complete });

    const completed = await http.graphql<{ completeTask: { taskId: string; complete: boolean } }>(
      'completeTask',
      { variables: { id: taskId }, token },
    );
    expect(completed.errors).toBeNull();
    expect(completed.data!.completeTask).toEqual({ taskId, complete: true });
    expect(await countsOf()).toEqual({ open: baseline.open, complete: baseline.complete + 1 });

    // Out-of-band: the row itself carries the owner, the flag and a real completed_at.
    const doneRows = await db.query<TaskRow>(
      'SELECT id, owner, title, complete, completed_at FROM tasks WHERE id = $1',
      [taskId],
    );
    expect(doneRows).toHaveLength(1);
    expect(doneRows[0]).toMatchObject({ id: taskId, owner: personId, title, complete: true });
    expect(doneRows[0].completed_at).not.toBeNull();

    const reopened = await http.graphql<{ reopenTask: { taskId: string; complete: boolean } }>(
      'reopenTask',
      { variables: { id: taskId }, token },
    );
    expect(reopened.errors).toBeNull();
    expect(reopened.data!.reopenTask).toEqual({ taskId, complete: false });
    expect(await countsOf()).toEqual({ open: baseline.open + 1, complete: baseline.complete });

    const relisted = await http.graphql<{ tasks: TaskSummary[] }>('listTasks', { token });
    expect(relisted.data!.tasks.find((task) => task.taskId === taskId)).toEqual({
      taskId,
      title,
      complete: false,
    });
    const reopenedRows = await db.query<TaskRow>(
      'SELECT complete, completed_at FROM tasks WHERE id = $1',
      [taskId],
    );
    expect(reopenedRows[0].complete).toBe(false);
    expect(reopenedRows[0].completed_at).toBeNull();

    // The session row exists while the journey uses it; sign-out must take it away.
    const liveSessions = await db.query<CountRow>(
      'SELECT COUNT(*)::int AS count FROM sessions WHERE token = $1',
      [token],
    );
    expect(liveSessions[0].count).toBe(1);

    const signedOut = await http.graphql<{ signOut: { signedOut: boolean } }>('signOut', {
      variables: { input: { sessionToken: token } },
    });
    expect(signedOut.errors).toBeNull();
    expect(signedOut.data!.signOut.signedOut).toBe(true);

    const after = await http.graphql<{ tasks: TaskSummary[] }>('listTasks', { token });
    expect(after.errorCode).toBe('SESSION_NOT_FOUND');
    expect(after.data).toBeNull();
    const deadSessions = await db.query<CountRow>(
      'SELECT COUNT(*)::int AS count FROM sessions WHERE token = $1',
      [token],
    );
    expect(deadSessions[0].count).toBe(0);
  });
});

import { Module } from '@nestjs/common';
import { E2EHttpModule } from '../../integrations/http/http.module';
import { E2EStackModule } from '../../platform/stack/stack.module';
import { E2EAuthService } from './e2e-auth.service';

/**
 * The bussiness layer's accounts capability: register/signIn/revokeSession/deleteAccount through
 * the public doors plus realm-admin population management. Needs the stack (keycloak address,
 * admin credentials) and the http transport (public GraphQL door).
 */
@Module({
  imports: [E2EStackModule, E2EHttpModule],
  providers: [E2EAuthService],
  exports: [E2EAuthService],
})
export class E2EAccountsModule {}

import { Injectable } from '@nestjs/common';
import { E2EHttpClient, E2EHttpService } from '../../integrations/http/e2e-http.service';
import { E2EStackService } from '../../platform/stack/e2e-stack.service';

export interface E2ESession {
  readonly sessionToken: string;
  /** Alias of sessionToken - both spellings landed in lane specs before the contract froze. */
  readonly token: string;
  readonly personId: string;
  readonly email: string;
}

export type PersonaName = 'owner' | 'other';

/**
 * The two identities the run-owned realm import (.starcistacks/dev/infra/compose/realm-todo.json)
 * seeds - the same bytes the dev stack ships, so a persona here is the same person a dev login is.
 */
const PERSONAS: Record<PersonaName, { email: string; password: string }> = {
  owner: { email: 'demo@todo.dev', password: 'todo-demo-pass' },
  other: { email: 'demo2@todo.dev', password: 'todo-demo-pass-2' },
};

interface AdminToken {
  readonly value: string;
  readonly expiresAt: number;
}

interface KeycloakUser {
  readonly id?: string;
}

/**
 * Identity for e2e specs: sign-in and session revocation go through the public GraphQL doors (the
 * only doors a real client has), while account create/delete go through the realm's admin REST API
 * using the run-owned admin credentials - test population management, never a flow under test.
 */
@Injectable()
export class E2EAuthService {
  private readonly sessions = new Map<string, E2ESession>();
  private admin: AdminToken | null = null;

  constructor(
    private readonly stack: E2EStackService,
    private readonly http: E2EHttpService,
  ) {}

  /** Signs in through the public door and keeps the session token; throws if no token comes back. */
  async signIn(email: string, password: string): Promise<E2ESession> {
    const observed = await this.http.graphql<{ signIn: { sessionToken: string; personId: string } }>(
      'signIn',
      { variables: { input: { email, password } } },
    );
    const sessionToken = observed.data?.signIn?.sessionToken;
    if (!sessionToken) {
      throw new Error(
        `sign-in for ${email} did not yield a sessionToken: ${observed.errorCode ?? observed.errorMessage ?? 'no error'}`,
      );
    }
    return { sessionToken, token: sessionToken, personId: observed.data!.signIn.personId, email };
  }

  /** Ends a session through the public signOut door; throws when the door refuses or stays silent. */
  async revokeSession(sessionToken: string): Promise<void> {
    const observed = await this.http.graphql<{ signOut: { signedOut: boolean } }>(
      'signOut',
      { variables: { input: { sessionToken } } },
    );
    if (!observed.data?.signOut?.signedOut) {
      throw new Error(
        `signOut did not confirm revocation: ${observed.errorCode ?? observed.errorMessage ?? 'no error'}`,
      );
    }
  }

  /** A cached session for a seeded realm identity. */
  async persona(name: PersonaName): Promise<E2ESession> {
    const known = this.sessions.get(name);
    if (known) return known;
    const identity = PERSONAS[name];
    if (!identity) throw new Error(`unknown persona ${name}`);
    const session = await this.signIn(identity.email, identity.password);
    this.sessions.set(name, session);
    return session;
  }

  /** Drops a cached persona session so a later step sees what an unauthenticated caller sees. */
  forgetPersona(name: PersonaName): void {
    this.sessions.delete(name);
  }

  personaEmail(name: PersonaName): string {
    return PERSONAS[name].email;
  }

  /**
   * Creates a realm user through the Keycloak admin API and returns { personId } - the realm user id,
   * which is also the `sub` sign-in yields. The account is real: signIn with the pair succeeds
   * afterwards through the public door.
   */
  async register(account: {
    email: string;
    password: string;
    firstName?: string;
    lastName?: string;
  }): Promise<{ personId: string }> {
    const response = await (await this.kcAdmin()).post('/admin/realms/todo/users', {
      username: account.email,
      email: account.email,
      firstName: account.firstName ?? 'E2E',
      lastName: account.lastName ?? 'User',
      enabled: true,
      emailVerified: true,
      requiredActions: [],
      credentials: [{ type: 'password', value: account.password, temporary: false }],
    });
    if (response.status !== 201 && response.status !== 409) {
      throw new Error(`keycloak user create for ${account.email} failed (${response.status}): ${JSON.stringify(response.data).slice(0, 400)}`);
    }
    return { personId: await this.findUserId(account.email) };
  }

  /** Earlier name for register() - kept for specs written before the accounts contract settled. */
  async createAccount(account: {
    email: string;
    password: string;
    firstName?: string;
    lastName?: string;
  }): Promise<{ personId: string }> {
    return this.register(account);
  }

  /** Deletes a realm user by personId (realm user id) or by email; a no-op when already gone. */
  async deleteAccount(personIdOrEmail: string): Promise<void> {
    const id = /^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(personIdOrEmail)
      ? personIdOrEmail
      : await this.findUserId(personIdOrEmail);
    if (!id) return;
    const response = await (await this.kcAdmin()).delete(`/admin/realms/todo/users/${id}`);
    if (response.status !== 204 && response.status !== 404) {
      throw new Error(`keycloak user delete for ${personIdOrEmail} failed (${response.status}): ${JSON.stringify(response.data).slice(0, 400)}`);
    }
  }

  private async findUserId(email: string): Promise<string> {
    const response = await (await this.kcAdmin()).get<KeycloakUser[]>('/admin/realms/todo/users', {
      email,
      exact: 'true',
    });
    const users = Array.isArray(response.data) ? response.data : [];
    return users[0]?.id ?? '';
  }

  /** An admin-API client scoped to the run-owned keycloak, bearer = cached master-realm admin token. */
  private async kcAdmin(): Promise<E2EHttpClient> {
    return new E2EHttpClient(this.stack.keycloakUrl, await this.adminToken());
  }

  private async adminToken(): Promise<string> {
    if (this.admin && Date.now() < this.admin.expiresAt) return this.admin.value;
    const response = await new E2EHttpClient(this.stack.keycloakUrl).postForm<{
      access_token?: string;
      expires_in?: number;
    }>('/realms/master/protocol/openid-connect/token', {
      grant_type: 'password',
      client_id: 'admin-cli',
      username: this.stack.keycloakAdmin.username,
      password: this.stack.keycloakAdmin.password,
    });
    const token = response.data?.access_token;
    if (!token) {
      throw new Error(`keycloak admin token refused (${response.status}): ${JSON.stringify(response.data).slice(0, 300)}`);
    }
    const expiresIn = response.data?.expires_in ?? 60;
    this.admin = { value: token, expiresAt: Date.now() + Math.max(expiresIn - 15, 5) * 1000 };
    return token;
  }
}

/**
 * The spec-facing surface of the test-infra module tree: every provider a journey can legitimately
 * reach for, re-exported so specs import the barrel (`../../infra`) instead of deep paths.
 */
export { TestingInfraModule } from './testing-infra.module';
export {
  TestContext,
  TestingInfraOptions,
  TESTING_INFRA_OPTIONS,
  E2E_BOOT_TIMEOUT_MS,
} from './testing-infra.options';
export { E2EStackModule } from './platform/stack/stack.module';
export { E2EStackService, E2EStackPorts, E2ETeardownReport } from './platform/stack/e2e-stack.service';
export { E2EDatabaseModule } from './platform/databases/database.module';
export { E2EDbService } from './platform/databases/e2e-db.service';
export { E2EHttpModule } from './integrations/http/http.module';
export {
  E2EHttpService,
  E2EHttpClient,
  E2EResponse,
  GRAPHQL_DOCUMENTS,
  GraphqlDocumentName,
  GraphqlObserved,
  GraphqlCallOptions,
  E2EGraphqlResponse,
  E2EGraphqlResult,
} from './integrations/http/e2e-http.service';
export { E2EGraphqlModule } from './integrations/graphql/graphql.module';
export { E2EGraphqlService } from './integrations/graphql/e2e-graphql.service';
export { E2EAccountsModule } from './bussiness/accounts/accounts.module';
export { E2EAuthService, E2ESession, PersonaName } from './bussiness/accounts/e2e-auth.service';

import { Injectable } from '@nestjs/common';
import { ApolloClient, HttpLink, InMemoryCache } from '@apollo/client';
import { DocumentNode, parse } from 'graphql';
import { E2EStackService } from '../../platform/stack/e2e-stack.service';
import {
  GRAPHQL_DOCUMENTS,
  GraphqlCallOptions,
  GraphqlDocumentName,
  GraphqlObserved,
} from '../http/e2e-http.service';

/**
 * The app's public surface is GraphQL, so the specs get a real GraphQL client, not only the raw
 * HTTP door: one ApolloClient per identity (bearer baked into its HttpLink, cached per token),
 * pointed at the run-owned api's /graphql endpoint. `query`/`mutate` take a DocumentNode (or a
 * GRAPHQL_DOCUMENTS key / raw document string) and answer with the same GraphqlObserved envelope
 * the HTTP door produces, so refusals stay assertions rather than thrown exceptions.
 */
@Injectable()
export class E2EGraphqlService {
  private readonly clients = new Map<string, ApolloClient>();

  constructor(private readonly stack: E2EStackService) {}

  /** A client for calls with no session attached. */
  anonymous(): ApolloClient {
    return this.forToken(undefined);
  }

  /** A client that carries this session's bearer on every operation. */
  forUser(token: string): ApolloClient {
    return this.forToken(token);
  }

  async query<TData = Record<string, unknown>>(
    document: GraphqlDocumentName | DocumentNode | string,
    options: GraphqlCallOptions = {},
  ): Promise<GraphqlObserved<TData>> {
    return this.call<TData>('query', document, options);
  }

  async mutate<TData = Record<string, unknown>>(
    document: GraphqlDocumentName | DocumentNode | string,
    options: GraphqlCallOptions = {},
  ): Promise<GraphqlObserved<TData>> {
    return this.call<TData>('mutate', document, options);
  }

  private async call<TData>(
    kind: 'query' | 'mutate',
    document: GraphqlDocumentName | DocumentNode | string,
    options: GraphqlCallOptions,
  ): Promise<GraphqlObserved<TData>> {
    const startedAt = Date.now();
    const node = toDocumentNode(document);
    try {
      const client = this.forToken(options.token);
      const result = (
        kind === 'mutate'
          ? await client.mutate({
              mutation: node,
              variables: options.variables ?? {},
              errorPolicy: 'all',
            })
          : await client.query({
              query: node,
              variables: options.variables ?? {},
              fetchPolicy: 'network-only',
              errorPolicy: 'all',
            })
      ) as { data?: unknown; error?: unknown; errors?: unknown };
      const errors = formattedErrorsOf(result);
      const firstExtensions = (errors?.[0]?.extensions ?? {}) as Record<string, unknown>;
      return {
        httpStatus: 200,
        data: (result.data ?? null) as TData | null,
        errors,
        errorCode: (firstExtensions.code as string) ?? null,
        errorMessage: (errors?.[0]?.message as string) ?? null,
        raw: result,
        durationMs: Date.now() - startedAt,
      };
    } catch (error) {
      // Transport-level failure (api down, abort, unparseable response): same envelope, status 0.
      return {
        httpStatus: 0,
        data: null,
        errors: null,
        errorCode: 'NETWORK_ERROR',
        errorMessage: error instanceof Error ? error.message : String(error),
        raw: error,
        durationMs: Date.now() - startedAt,
      };
    }
  }

  private forToken(token: string | undefined): ApolloClient {
    const key = token ?? '';
    let client = this.clients.get(key);
    if (!client) {
      client = new ApolloClient({
        cache: new InMemoryCache(),
        link: new HttpLink({
          uri: `${this.stack.baseUrl}/graphql`,
          fetch,
          headers: token ? { authorization: `Bearer ${token}` } : undefined,
        }),
        defaultOptions: {
          // e2e reads must observe what the door answered just now, never a warmed cache.
          watchQuery: { fetchPolicy: 'network-only' },
          query: { fetchPolicy: 'network-only' },
        },
      });
      this.clients.set(key, client);
    }
    return client;
  }
}

function toDocumentNode(document: GraphqlDocumentName | DocumentNode | string): DocumentNode {
  if (typeof document !== 'string') return document;
  return parse((GRAPHQL_DOCUMENTS as Record<string, string>)[document] ?? document);
}

/** AC4 reports GraphQL refusals as a CombinedGraphQLErrors on `.error`; older shapes used `.errors`. */
function formattedErrorsOf(result: { error?: unknown; errors?: unknown }): Record<string, unknown>[] | null {
  const combined = (result.error as { errors?: unknown } | undefined)?.errors;
  if (Array.isArray(combined) && combined.length) return combined as Record<string, unknown>[];
  if (Array.isArray(result.errors) && result.errors.length) return result.errors as Record<string, unknown>[];
  if (result.error) {
    const message = (result.error as { message?: string }).message ?? String(result.error);
    return [{ message }];
  }
  return null;
}

import { Module } from '@nestjs/common';
import { E2EStackModule } from '../../platform/stack/stack.module';
import { E2EGraphqlService } from './e2e-graphql.service';

/**
 * The integrations layer's GraphQL capability: per-user ApolloClient instances against the
 * run-owned api's /graphql door. Depends on the stack module for the api address.
 */
@Module({
  imports: [E2EStackModule],
  providers: [E2EGraphqlService],
  exports: [E2EGraphqlService],
})
export class E2EGraphqlModule {}

import { Injectable } from '@nestjs/common';
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { E2EStackService } from '../../platform/stack/e2e-stack.service';

/**
 * The public transport contract, and nothing else. Every call is an HTTP POST to the api's single
 * /graphql door with a {query, variables} body. No spec imports a service class, a repository, a
 * handler or an entity; preconditions are created by the public operations that create them.
 *
 * These are the operations the resolvers under src/features/todo/graphql actually register. Notes
 * carried over from the retired lib/client.js: there is no single-task query (a task is read back out
 * of `tasks`), and there is no public door for completing or skipping a recurrence occurrence.
 */
export const GRAPHQL_DOCUMENTS = {
  signIn: 'mutation SignIn($input: SignInInput!) { signIn(input: $input) { sessionToken personId } }',
  signOut: 'mutation SignOut($input: SignOutInput!) { signOut(input: $input) { signedOut } }',
  createTask: 'mutation CreateTask($input: CreateTaskInput!) { createTask(input: $input) { taskId title } }',
  listTasks: 'query { tasks { taskId title complete } }',
  completeTask: 'mutation CompleteTask($id: ID!) { completeTask(id: $id) { taskId complete } }',
  reopenTask: 'mutation ReopenTask($id: ID!) { reopenTask(id: $id) { taskId complete } }',
  deleteTask: 'mutation DeleteTask($id: ID!) { deleteTask(id: $id) { deleted } }',
  invite: 'mutation Invite($input: InviteInput!) { invite(input: $input) { invitationId taskId email role status } }',
  acceptInvitation: 'mutation Accept($input: AcceptInvitationInput!) { acceptInvitation(input: $input) { invitationId role status } }',
  revokeCollaborator: 'mutation Revoke($input: RevokeCollaboratorInput!) { revokeCollaborator(input: $input) { invitationId status } }',
  collaborators: 'query Collaborators($taskId: ID!) { collaborators(taskId: $taskId) { invitationId email role status } }',
  auditLog: 'query { auditLog { at action target } }',
  exportMyData: 'query { exportMyData { at action target } }',
  requestErasure: 'mutation { requestErasure { requestId state } }',
  completeErasure: 'mutation CompleteErasure($requestId: ID!) { completeErasure(requestId: $requestId) { requestId state } }',
  makeRecurring: 'mutation MakeRecurring($input: MakeRecurringInput!) { makeRecurring(input: $input) { ruleId title frequency timeZone time startDate } }',
  editRecurrence: 'mutation EditRecurrence($input: EditRecurrenceInput!) { editRecurrence(input: $input) { ruleId frequency timeZone time } }',
  endRecurrence: 'mutation EndRecurrence($input: EndRecurrenceInput!) { endRecurrence(input: $input) { ruleId endedAt orphanedCount } }',
  upcomingOccurrences: 'query Upcoming($ruleId: String!) { upcomingOccurrences(ruleId: $ruleId) { ruleId materialised { occurrenceId localDate dueAtUtc status } previewDates } }',
  notificationPreferences: 'query Prefs($channel: String) { notificationPreferences(channel: $channel) { channel unsubscribed digestWindowMinutes } }',
  usage: 'query { planUsage { plan cap activeCount } }',
} as const;

export type GraphqlDocumentName = keyof typeof GRAPHQL_DOCUMENTS;

export interface GraphqlObserved<TData = Record<string, unknown>> {
  readonly httpStatus: number;
  readonly data: TData | null;
  readonly errors: ReadonlyArray<Record<string, unknown>> | null;
  readonly errorCode: string | null;
  readonly errorMessage: string | null;
  readonly raw: unknown;
  readonly durationMs: number;
}

export interface GraphqlCallOptions {
  readonly variables?: Record<string, unknown>;
  readonly token?: string;
}

/** Aliases kept for lanes that named the envelope before this file landed - same shape. */
export type E2EGraphqlResponse<TData = Record<string, unknown>> = GraphqlObserved<TData>;
export type E2EGraphqlResult<TData = Record<string, unknown>> = GraphqlObserved<TData>;

export interface E2EResponse<T = unknown> {
  readonly status: number;
  readonly data: T;
  readonly headers: Record<string, string>;
}

/**
 * One HTTP client bound to one service and one identity - the "axios-per-user" door: an axios.create
 * instance with the service's baseURL and the session bearer preset, wrapped so callers read
 * `.status`/`.data` like an AxiosResponse. Refusals resolve (validateStatus accepts everything):
 * a spec needs the 4xx body, not a rejected promise.
 */
export class E2EHttpClient {
  private readonly axios: AxiosInstance;

  constructor(
    private readonly baseUrl: string,
    private readonly token?: string,
  ) {
    this.axios = axios.create({
      baseURL: baseUrl,
      timeout: 15_000,
      validateStatus: () => true,
      headers: token ? { authorization: `Bearer ${token}` } : undefined,
    });
  }

  async get<T = unknown>(path: string, params?: Record<string, string>): Promise<E2EResponse<T>> {
    return this.wrap(await this.axios.get<T>(path, { params }));
  }

  async post<T = unknown>(path: string, body: unknown, headers: Record<string, string> = {}): Promise<E2EResponse<T>> {
    return this.wrap(await this.axios.post<T>(path, body, { headers }));
  }

  async put<T = unknown>(path: string, body: unknown, headers: Record<string, string> = {}): Promise<E2EResponse<T>> {
    return this.wrap(await this.axios.put<T>(path, body, { headers }));
  }

  async patch<T = unknown>(path: string, body: unknown, headers: Record<string, string> = {}): Promise<E2EResponse<T>> {
    return this.wrap(await this.axios.patch<T>(path, body, { headers }));
  }

  async delete<T = unknown>(path: string): Promise<E2EResponse<T>> {
    return this.wrap(await this.axios.delete<T>(path));
  }

  async postForm<T = unknown>(path: string, form: Record<string, string>): Promise<E2EResponse<T>> {
    return this.wrap(await this.axios.post<T>(path, new URLSearchParams(form).toString(), {
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
    }));
  }

  /**
   * One GraphQL operation over HTTP through this client's bearer. `query` is a raw GraphQL document;
   * the envelope is the same shape E2EHttpService.graphql returns.
   */
  async graphql<TData = Record<string, unknown>>(
    query: string,
    variables?: Record<string, unknown>,
  ): Promise<GraphqlObserved<TData>> {
    const startedAt = Date.now();
    const response = await this.post<Record<string, unknown>>('/graphql', { query, variables: variables ?? {} });
    return envelopeOf(response, startedAt);
  }

  private wrap<T>(response: AxiosResponse<T>): E2EResponse<T> {
    const headers: Record<string, string> = {};
    for (const [key, value] of Object.entries(response.headers ?? {})) {
      headers[key] = Array.isArray(value) ? value.join(', ') : String(value);
    }
    return { status: response.status, data: response.data, headers };
  }
}

/**
 * Per-user HTTP transport for the run-owned api. `forUser(token)` returns an E2EHttpClient scoped to
 * the spec's api baseURL with the bearer preset; `graphql(...)` is the typed convenience wrapper most
 * specs use.
 */
@Injectable()
export class E2EHttpService {
  private readonly clients = new Map<string, E2EHttpClient>();

  constructor(private readonly stack: E2EStackService) {}

  /** A client for calls with no session attached. */
  anonymous(): E2EHttpClient {
    return this.forToken(undefined);
  }

  /** A client that carries this session's bearer on every request. */
  forUser(token: string): E2EHttpClient {
    return this.forToken(token);
  }

  /**
   * One GraphQL operation over HTTP. `document` is a GRAPHQL_DOCUMENTS key or a raw query string for
   * shapes the registry does not name yet.
   */
  async graphql<TData = Record<string, unknown>>(
    document: GraphqlDocumentName | string,
    options: GraphqlCallOptions = {},
  ): Promise<GraphqlObserved<TData>> {
    const query = (GRAPHQL_DOCUMENTS as Record<string, string>)[document] ?? document;
    return this.forToken(options.token).graphql<TData>(query, options.variables);
  }

  /**
   * A client for one identity. `client()` is anonymous; `client({ bearerToken })` carries that
   * session's bearer on every request.
   */
  client(options: { bearerToken?: string } = {}): E2EHttpClient {
    return this.forToken(options.bearerToken);
  }

  private forToken(token: string | undefined): E2EHttpClient {
    const key = token ?? '';
    let client = this.clients.get(key);
    if (!client) {
      client = new E2EHttpClient(this.stack.baseUrl, token);
      this.clients.set(key, client);
    }
    return client;
  }
}

function envelopeOf<TData>(response: E2EResponse<Record<string, unknown>>, startedAt: number): GraphqlObserved<TData> {
  const envelope = typeof response.data === 'object' && response.data !== null
    ? response.data
    : { unparsableBody: String(response.data).slice(0, 2000) };
  const errors = Array.isArray(envelope.errors) ? (envelope.errors as Record<string, unknown>[]) : null;
  const firstExtensions = (errors?.[0]?.extensions ?? {}) as Record<string, unknown>;
  return {
    httpStatus: response.status,
    data: (envelope.data ?? null) as TData | null,
    errors,
    errorCode: (firstExtensions.code as string) ?? null,
    errorMessage: (errors?.[0]?.message as string) ?? null,
    raw: envelope,
    durationMs: Date.now() - startedAt,
  };
}

